const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=1280,H=720,worldW=2920,ground=568;let dpr=1,scale=1,cam=0,last=0,started=false,paused=false,toastTimer=0,shake=0;
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);scale=canvas.width/W;ctx.setTransform(scale,0,0,scale,0,0)}window.addEventListener('resize',resize);resize();
const keys={};window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!e.repeat)press(k)});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
const touchKeys={left:'a',right:'d',jump:' ',attack:'j',wind:'k',use:'e'};document.querySelectorAll('.touch button').forEach(b=>{const key=touchKeys[b.dataset.key];b.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;if(key===' ')press(' ');else press(key)});for(const ev of ['pointerup','pointerleave','pointercancel'])b.addEventListener(ev,()=>keys[key]=false)});
const player={x:120,y:ground,z:0,vx:0,vy:0,vz:0,hp:100,face:1,onGround:true,atk:0,wind:0,inv:0,anim:0,score:0};
let enemies=[{x:590,z:0,hp:2,stun:0,hit:0,face:-1},{x:850,z:32,hp:2,stun:0,hit:0,face:-1},{x:1900,z:0,hp:2,stun:0,hit:0,face:-1},{x:2140,z:35,hp:3,stun:0,hit:0,face:-1}], shards=[{x:380,z:8,got:false},{x:1010,z:40,got:false},{x:1600,z:0,got:false},{x:2400,z:20,got:false}],platforms=[{x:320,w:130,y:475},{x:730,w:145,y:435},{x:1200,w:155,y:480},{x:1610,w:140,y:438},{x:2300,w:150,y:455}];
let dial=[0,0,0],target=[1,3,2],selected=0,puzzleSolved=false,focus=0,gateOpen=false,finish=false,gameTime=0;
const symbols=['☼','◒','≈','◉'];
function press(k){if(!started)return;if(k==='j')attack();if(k==='k')wind();if(k==='e')interact();if(k==='f')reveal();if(k==='arrowup'||k==='w'){if(inPuzzle()){selected=(selected+2)%3;updateDials()}}if(k==='arrowdown'||k==='s'){if(inPuzzle()){selected=(selected+1)%3;updateDials()}}if(k==='r'&&(finish||player.hp<=0))resetGame()}
function showToast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');toastTimer=2.3}
function inPuzzle(){return player.x>1390&&player.x<1775&&!puzzleSolved}
function updateDials(){document.getElementById('dials').innerHTML=dial.map((v,i)=>`<div class="dial ${i===selected?'selected':''}">${symbols[v]}<small>${['TIDE','MOON','EYE'][i]}</small></div>`).join('')}
function attack(){if(player.atk>0)return;player.atk=.34;player.anim=0;let hit=false;for(const e of enemies){if(e.hp<=0)continue;const dx=e.x-player.x;if(Math.abs(dx)<92&&Math.abs(e.z-player.z)<65&&Math.sign(dx)===player.face){e.hp--;e.stun=e.hp<=0?4.5:0.36;e.hit=.3;e.x+=player.face*24;shake=4;hit=true;if(e.hp<=0){showToast('WRAITH BROKEN — FINISH WITH E');player.score++}else showToast('CLEAN HIT')} }if(!hit){} }
function wind(){if(player.wind>0)return;player.wind=1.1;let nearest=null,dist=245;for(const e of enemies){let d=Math.hypot(e.x-player.x,(e.z-player.z)*1.25);if(e.hp>0&&d<dist){dist=d;nearest=e}}if(nearest){nearest.stun=Math.max(nearest.stun,1.3);nearest.x=player.x+player.face*65;nearest.z=player.z;nearest.hit=.4;showToast('WIND SNARE');shake=2}else showToast('WIND RING')}
function interact(){if(inPuzzle()){dial[selected]=(dial[selected]+1)%4;updateDials();if(dial.every((v,i)=>v===target[i])){puzzleSolved=true;gateOpen=true;document.getElementById('puzzle').classList.remove('on');showToast('THE ASTRAL LOCK YIELDS');document.getElementById('objective').textContent='Cross the opened bridge'}return}
if(finish){resetGame();return}let e=enemies.find(e=>e.hp===0&&e.stun>0&&Math.abs(e.x-player.x)<110&&Math.abs(e.z-player.z)<80);if(e){e.hp=-1;e.stun=0;player.hp=Math.min(100,player.hp+22);player.score++;showToast('FINISHER · +22 VITALITY');shake=8;return}if(player.x>worldW-280){if(!gateOpen){showToast('THE ASTRAL LOCK IS STILL SEALED');return}finish=true;document.getElementById('objective').textContent='Citadel liberated';document.getElementById('overlay').classList.remove('hidden');document.querySelector('.eyebrow').textContent='THE SUNKEN CROWN IS YOURS';document.querySelector('.panel h1').innerHTML='DAWN RETURNS<span>THE CITADEL REMEMBERS</span>';document.querySelector('.panel p').textContent=`You broke the astral lock and sent ${player.score} wraiths back into the rift. The old road is open — for now.`;document.getElementById('start').textContent='PLAY AGAIN';return}showToast('NOTHING TO USE HERE')}
function reveal(){if(inPuzzle()){focus=2.4;showToast('FOCUS: TIDE → MOON → WATCHING EYE')}else if(player.x>1000&&player.x<1390)showToast('THE OBSERVATORY LIES BEYOND THE BROKEN ARCH')}
function resetGame(){player.x=120;player.y=ground;player.z=0;player.vx=player.vy=player.vz=0;player.hp=100;player.score=0;enemies=[{x:590,z:0,hp:2,stun:0,hit:0,face:-1},{x:850,z:32,hp:2,stun:0,hit:0,face:-1},{x:1900,z:0,hp:2,stun:0,hit:0,face:-1},{x:2140,z:35,hp:3,stun:0,hit:0,face:-1}];shards.forEach(s=>s.got=false);dial=[0,0,0];selected=0;puzzleSolved=gateOpen=finish=false;document.getElementById('objective').textContent='Reach the old observatory';document.getElementById('overlay').classList.add('hidden');updateDials();}
document.getElementById('start').onclick=()=>{if(finish||player.hp<=0)resetGame();started=true;document.getElementById('overlay').classList.add('hidden');showToast('THE WIND REMEMBERS YOUR NAME')};updateDials();
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function lerp(a,b,t){return a+(b-a)*t}
function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function poly(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
function line(x1,y1,x2,y2,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function drawBackground(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#101d2c');g.addColorStop(.52,'#30434c');g.addColorStop(1,'#111a20');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);let moon=ctx.createRadialGradient(910,170,5,910,170,180);moon.addColorStop(0,'#e6d3a9aa');moon.addColorStop(.2,'#bfc9bf52');moon.addColorStop(1,'#9cc5bd00');ctx.fillStyle=moon;ctx.fillRect(650,0,520,430);ctx.fillStyle='#ded9be';ctx.beginPath();ctx.arc(910,168,39,0,Math.PI*2);ctx.fill();ctx.fillStyle='#172632';ctx.beginPath();ctx.arc(927,153,37,0,Math.PI*2);ctx.fill();
// distant cliffs and broken towers
ctx.save();ctx.translate(-cam*.18,0);poly([[-200,440],[80,286],[180,365],[360,244],[500,408],[650,300],[820,406],[1020,220],[1140,356],[1320,275],[1510,420],[1710,305],[1880,405],[2090,255],[2220,400],[2460,245],[2650,410],[2920,300],[3200,450]],'#253942');poly([[-100,477],[130,380],[250,452],[450,325],[590,455],[790,358],[960,447],[1160,306],[1290,430],[1450,352],[1620,465],[1840,344],[2030,452],[2220,330],[2420,470],[2620,352],[2810,450],[3040,330],[3200,478]],'#1b2b34');
for(let i=0;i<8;i++){let x=i*440+100,y=335+Math.sin(i*9)*30;ctx.globalAlpha=.22;poly([[x-25,y],[x-25,y-120],[x-12,y-145],[x,y-120],[x+14,y-145],[x+24,y-120],[x+24,y]],'#0c1a21');ctx.globalAlpha=1}
ctx.restore();for(let i=0;i<90;i++){let x=(i*173+gameTime*6)%(W+40)-20,y=(i*79+Math.sin(gameTime*.4+i)*18)%450;ctx.globalAlpha=.16+Math.sin(i+gameTime)*.12;ctx.fillStyle=i%4?'#d9d4b8':'#8de1dd';ctx.fillRect(x,y,2,2)}ctx.globalAlpha=1;
// world ground plane with depth
ctx.save();ctx.translate(-cam,0);poly([[0,ground],[worldW,ground],[worldW,700],[0,700]],'#202a2e');poly([[0,ground],[worldW,ground],[worldW,ground+24],[0,ground+24]],'#53605a');line(0,ground,worldW,ground,'#a2a27d',2);
for(let x=0;x<worldW;x+=110){line(x,ground+8,x+48,ground+8,'#d7c68c22',1);poly([[x+19,ground+35],[x+42,ground+31],[x+58,ground+35],[x+31,ground+38]],'#82908920')}
// water below the causeway
let water=ctx.createLinearGradient(0,ground+100,0,720);water.addColorStop(0,'#14323b');water.addColorStop(1,'#08151e');ctx.fillStyle=water;ctx.fillRect(0,ground+100,worldW,170);for(let i=0;i<45;i++){let wx=(i*137+gameTime*27)%worldW;line(wx,ground+125+(i%7)*15,wx+22,ground+125+(i%7)*15,'#68bbc433',1)}
// platforms
platforms.forEach(p=>{ctx.fillStyle='#59635c';ctx.fillRect(p.x,p.y,p.w,12);poly([[p.x,p.y+12],[p.x+p.w,p.y+12],[p.x+p.w-12,p.y+32],[p.x+8,p.y+32]],'#303b3c');line(p.x,p.y,p.x+p.w,p.y,'#c4b889',2);for(let n=0;n<3;n++)line(p.x+15+n*40,p.y+14,p.x+23+n*40,p.y+26,'#89908a55',2)});

// ruined pillars, arch and observatory
for(let i=0;i<11;i++){let x=160+i*275,h=100+(i%3)*55;ctx.fillStyle=i%2?'#394540':'#4a5047';ctx.fillRect(x,ground-h,22,h);ctx.fillRect(x-9,ground-h-8,40,12);ctx.fillStyle='#252f32';ctx.fillRect(x+22,ground-h+15,6,h-15);line(x-4,ground-h+33,x+17,ground-h+40,'#b2a57a55',2)}
// first arch
ctx.fillStyle='#51564a';ctx.fillRect(1070,365,31,203);ctx.fillRect(1240,365,31,203);ctx.fillRect(1058,355,226,20);poly([[1068,355],[1100,330],[1238,330],[1272,355]],'#60604e');line(1100,345,1238,345,'#ddc38166',2);
// astral monument with ring and dials
ctx.fillStyle='#5e5c4a';ctx.fillRect(1450,370,54,198);ctx.fillRect(1715,370,54,198);ctx.fillRect(1438,357,292,20);ctx.save();ctx.translate(1584,366);ctx.strokeStyle='#c8ad67aa';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,85,Math.PI,0);ctx.stroke();ctx.beginPath();ctx.arc(0,0,65,Math.PI,0);ctx.stroke();ctx.strokeStyle='#b9e8d988';ctx.lineWidth=2;for(let i=0;i<9;i++){let a=Math.PI+(i/8)*Math.PI;line(Math.cos(a)*72,Math.sin(a)*72,Math.cos(a)*88,Math.sin(a)*88,'#d7c37a88',2)}ctx.restore();for(let i=0;i<3;i++){let x=1494+i*90;ctx.strokeStyle='#a1ded4';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,474,20,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#d2bd7a';ctx.beginPath();ctx.arc(x,474,5,0,Math.PI*2);ctx.fill()}
// sealed gate and bridge
ctx.fillStyle=gateOpen?'#334744':'#362e31';ctx.fillRect(1770,340,38,228);ctx.fillRect(1950,340,38,228);ctx.fillRect(1760,333,200,15);if(!gateOpen){ctx.fillStyle='#d15f56aa';ctx.fillRect(1795,360,3,200);ctx.fillRect(1835,360,3,200);ctx.fillRect(1875,360,3,200);ctx.fillRect(1915,360,3,200)}else{for(let i=0;i<5;i++)line(1780+i*39,390,1802+i*39,560,'#85e2d655',2)}
// far temple at horizon
ctx.fillStyle='#323c3d';for(let i=0;i<5;i++){let xx=2485+i*53;ctx.fillRect(xx,425-(i%2)*18,19,143+(i%2)*18);ctx.fillRect(xx-7,418-(i%2)*18,32,8)}ctx.fillRect(2465,413,292,17);poly([[2475,413],[2510,389],[2712,389],[2747,413]],'#4b5048');
// hanging lanterns and grass
for(let i=0;i<18;i++){let x=80+i*157;let yy=ground-95-(i%3)*22;line(x,yy-70,x,yy,'#c7b36d55',1);ctx.fillStyle='#e3b862';ctx.globalAlpha=.4+Math.sin(gameTime*2+i)*.15;ctx.beginPath();ctx.arc(x,yy+5,4,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;if(i%2===0){ctx.strokeStyle='#8c9a72';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+45,ground);ctx.quadraticCurveTo(x+40,ground-20,x+33,ground-24);ctx.moveTo(x+48,ground);ctx.quadraticCurveTo(x+54,ground-18,x+62,ground-20);ctx.stroke()}}
// glowing collectible motes
shards.forEach(s=>{if(s.got)return;let sy=ground-52-s.z*.3+Math.sin(gameTime*3+s.x)*7;ctx.save();ctx.translate(s.x,sy);ctx.rotate(gameTime*1.1);ctx.shadowBlur=18;ctx.shadowColor='#69d9d8';ctx.fillStyle='#9df4df';ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(6,0);ctx.lineTo(0,9);ctx.lineTo(-6,0);ctx.closePath();ctx.fill();ctx.restore()});
// characters
for(const e of enemies)if(e.hp>=0)drawEnemy(e);
drawPlayer();ctx.restore();
// scene lighting and lower fade
let glow=ctx.createRadialGradient(620,520,20,620,520,500);glow.addColorStop(0,'#dfa85810');glow.addColorStop(1,'#00000000');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
}
function drawEnemy(e){let x=e.x,y=ground-e.z*.42,dead=e.hp===0,fl=e.hit>0;ctx.save();ctx.translate(x,y);let bob=Math.sin(gameTime*4+e.x)*3;if(dead){ctx.globalAlpha=clamp(e.stun/4.5,0,1)*.62;ctx.translate(0,-12)}if(e.stun>0&&!dead){ctx.globalAlpha=.86;ctx.shadowBlur=18;ctx.shadowColor='#8eece2'}// shadow
ctx.globalAlpha*=.8;ctx.fillStyle='#091116';ctx.beginPath();ctx.ellipse(0,3,31,8,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=dead?.62:1;
// floating ragged wraith
ctx.fillStyle=fl?'#f0d7b4':'#9baba7';ctx.beginPath();ctx.moveTo(-20,-8+bob);ctx.quadraticCurveTo(-31,-41+bob,-12,-67+bob);ctx.quadraticCurveTo(3,-81+bob,20,-60+bob);ctx.quadraticCurveTo(32,-34+bob,18,-8+bob);ctx.lineTo(12,1);ctx.lineTo(4,-9);ctx.lineTo(-5,3);ctx.lineTo(-12,-7);ctx.closePath();ctx.fill();ctx.fillStyle='#1a2a31';ctx.beginPath();ctx.ellipse(2,-56+bob,13,16,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f6ba72';ctx.fillRect(-6,-59+bob,5,3);ctx.fillRect(5,-59+bob,5,3);ctx.strokeStyle='#d7e2cf';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-15,-34+bob);ctx.lineTo(-31,-19+bob);ctx.moveTo(15,-34+bob);ctx.lineTo(28,-21+bob);ctx.stroke();if(e.hp>0){ctx.fillStyle='#341d25';ctx.fillRect(-22,-88,44,4);ctx.fillStyle='#e18b76';ctx.fillRect(-22,-88,44*(e.hp/3),4)}if(e.stun>0&&e.hp===0){ctx.fillStyle='#fae1a3';ctx.font='15px serif';ctx.fillText('✦',-4,-92)}ctx.restore()}
function drawPlayer(){let x=player.x,y=player.y-player.z*.42,air=ground-player.y;ctx.save();ctx.translate(x,y);let dir=player.face,walk=Math.sin(player.anim*10)*3;ctx.scale(dir,1);if(player.inv>0&&Math.floor(gameTime*16)%2)ctx.globalAlpha=.4;
// shadow
ctx.fillStyle='#070d12aa';ctx.beginPath();ctx.ellipse(0,air+5,25-Math.min(10,air*.08),7,0,0,Math.PI*2);ctx.fill();
// wind aura
if(player.wind>0){ctx.strokeStyle='#8fe4dc66';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,-30,45+Math.sin(gameTime*15)*8,36,0,0,Math.PI*2);ctx.stroke()}
// cape
ctx.fillStyle='#812f35';ctx.beginPath();ctx.moveTo(-8,-54);ctx.quadraticCurveTo(-28,-28+walk,-25,4);ctx.lineTo(-8,-4);ctx.lineTo(3,-39);ctx.closePath();ctx.fill();ctx.fillStyle='#b05248';ctx.beginPath();ctx.moveTo(-12,-49);ctx.quadraticCurveTo(-16,-25,-14,-8);ctx.lineTo(-6,-13);ctx.closePath();ctx.fill();
// legs
ctx.strokeStyle='#263541';ctx.lineWidth=8;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-3,-21);ctx.lineTo(-7+walk,-4);ctx.moveTo(7,-21);ctx.lineTo(11-walk,-4);ctx.stroke();ctx.strokeStyle='#b89b72';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-11+walk,-3);ctx.lineTo(-2+walk,-3);ctx.moveTo(7-walk,-3);ctx.lineTo(17-walk,-3);ctx.stroke();
// torso tunic
ctx.fillStyle='#d3b87c';ctx.beginPath();ctx.moveTo(-13,-52);ctx.lineTo(11,-52);ctx.lineTo(16,-23);ctx.lineTo(-11,-22);ctx.closePath();ctx.fill();ctx.fillStyle='#293e4b';ctx.fillRect(-9,-47,17,20);ctx.fillStyle='#e4c47d';ctx.fillRect(0,-48,3,25);
// arm and bracer
ctx.strokeStyle='#d2b37b';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-10,-47);ctx.lineTo(-19,-34);ctx.moveTo(11,-46);ctx.lineTo(17,-34);ctx.stroke();ctx.strokeStyle='#7fa5a1';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(-19,-34);ctx.lineTo(-17,-27);ctx.stroke();
// head hood
ctx.fillStyle='#d2a477';ctx.beginPath();ctx.arc(0,-62,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='#273b46';ctx.beginPath();ctx.moveTo(-15,-60);ctx.quadraticCurveTo(-17,-83,2,-81);ctx.quadraticCurveTo(15,-77,14,-62);ctx.lineTo(9,-66);ctx.lineTo(-13,-64);ctx.closePath();ctx.fill();ctx.fillStyle='#d6bd82';ctx.beginPath();ctx.moveTo(-13,-63);ctx.lineTo(15,-63);ctx.lineTo(11,-57);ctx.lineTo(-11,-58);ctx.closePath();ctx.fill();ctx.fillStyle='#e8cc8d';ctx.fillRect(2,-63,3,2);
// blade attack arc / sword
ctx.strokeStyle='#d9e7dc';ctx.lineWidth=4;ctx.lineCap='round';if(player.atk>.12){ctx.save();ctx.rotate(-.8+((.34-player.atk)/.34)*1.6);ctx.beginPath();ctx.moveTo(15,-39);ctx.lineTo(53,-62);ctx.stroke();ctx.strokeStyle='#a5dcd5';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-25,56,-1.05,.2);ctx.stroke();ctx.restore()}else{ctx.beginPath();ctx.moveTo(17,-35);ctx.lineTo(29,-55);ctx.stroke()}ctx.strokeStyle='#b48242';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(13,-36);ctx.lineTo(20,-32);ctx.stroke();ctx.restore()}

